/** Decoder for QR generated by champro.mrhien.com/qr-excel.html.
 * Envelope: {cp:1,set,seq:1,total:1,type,sha256,data} with gzip+base64url. */
const MAX_QR_TEXT=25000, MAX_JSON=2*1024*1024;
export async function decodeChamProQR(raw){
 if(typeof raw!=='string'||raw.length>MAX_QR_TEXT)throw Error('Mã QR quá dài hoặc không hợp lệ');
 let envelope;try{envelope=JSON.parse(raw);}catch{throw Error('QR không phải định dạng QR Web của ChấmPro');}
 if(envelope?.cp!==1||envelope.seq!==1||envelope.total!==1||!['student_list','answer_key'].includes(envelope.type)||typeof envelope.data!=='string'||!envelope.sha256)throw Error('Không nhận dạng được QR ChấmPro Web hoặc QR không đầy đủ');
 if(!/^[A-Za-z0-9_-]+$/.test(envelope.data))throw Error('Dữ liệu QR bị sai mã hóa');
 const str=envelope.data.replace(/-/g,'+').replace(/_/g,'/');
 let b;try{const binary=atob(str.padEnd(Math.ceil(str.length/4)*4,'='));b=Uint8Array.from(binary,c=>c.charCodeAt(0));}catch{throw Error('Không giải mã được dữ liệu QR');}
 const digest=new Uint8Array(await crypto.subtle.digest('SHA-256',b));
 const actual=Array.from(digest,x=>x.toString(16).padStart(2,'0')).join('');
 if(actual.toLowerCase()!==String(envelope.sha256).toLowerCase())throw Error('QR sai mã xác thực SHA-256, không nhập');
 let bytes;
 if(typeof DecompressionStream!=='undefined'){
   const stream=new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'));
   bytes=new Uint8Array(await new Response(stream).arrayBuffer());
 }else if(globalThis.pako?.ungzip){bytes=globalThis.pako.ungzip(b);}
 else throw Error('Trình duyệt chưa hỗ trợ giải nén gzip; cần tải thư viện Pako');
 if(bytes.length>MAX_JSON)throw Error('QR chứa dữ liệu quá lớn');
 let data;try{data=JSON.parse(new TextDecoder().decode(bytes));}catch{throw Error('Nội dung QR không phải JSON hợp lệ');}
 if(data?.app!=='ChamPro'||data.v!==1||data.type!==envelope.type)throw Error('Nội dung QR không đúng phiên bản ChấmPro');
 return data;
}
export const normalizeSbd=s=>String(s??'').replace(/\.0$/,'').trim();
export function studentsFromQR(data){
 if(data?.type!=='student_list'||!Array.isArray(data.students)||data.students.length>500)throw Error('QR danh sách học sinh không hợp lệ');
 const seen=new Set();const output=[];
 for(const s of data.students){const sbd=normalizeSbd(s.candidate_no),name=String(s.full_name||'').trim();if(!/^\d{1,12}$/.test(sbd)||!name||seen.has(sbd))continue;seen.add(sbd);output.push({sbd,name,classroom:String(data.class_name||'').trim(),parentZalo1:String(s.parent_zalo_1||''),parentZalo2:String(s.parent_zalo_2||''),note:String(s.note||'')});}
 if(!output.length)throw Error('QR không có học sinh hợp lệ');
 return output;
}
export function keysFromQR(data,exam){
 if(data?.type!=='answer_key'||!data.answer_keys||!exam)throw Error('QR đáp án không hợp lệ');
 const c=data.part_counts||{};
 if(['I','II','III'].some(p=>Number(c[p])!==Number(exam.counts[p])))throw Error(`Số câu trong QR (${c.I}/${c.II}/${c.III}) khác cấu hình môn ${exam.subject||''} (${exam.counts.I}/${exam.counts.II}/${exam.counts.III})`);
 if(Number(data.code_digits)!==Number(exam.digits))throw Error('Số chữ số mã đề trong QR khác cấu hình môn kiểm tra');
 const entries=Object.entries(data.answer_keys);if(!entries.length||entries.length>100)throw Error('QR không có mã đề hợp lệ');
 const result={};
 for(const [code,record] of entries){
  if(!new RegExp('^\\d{'+exam.digits+'}$').test(code))throw Error('Mã đề không hợp lệ: '+code);
  const out={I:[],II:[],III:[]};
  for(const part of ['I','II','III']){
   const arr=record[part];if(!Array.isArray(arr)||arr.length!==exam.counts[part])throw Error(`QR thiếu đáp án phần ${part} mã ${code}`);
   for(const item of arr){
    if(item?.award_all===true||item?.cancelled===true){out[part].push('ALL');continue;}
    if(part==='II'){
     const val=String(item?.answer||'').toUpperCase().replaceAll('D','Đ');if(!/^[ĐS]{4}$/.test(val))throw Error('QR có ý Đúng/Sai không hợp lệ');out[part].push(val);
    }else{
     const vals=item?.accepted;if(!Array.isArray(vals)||!vals.length)throw Error('QR có câu thiếu đáp án');
     const value=vals.map(v=>String(v).trim()).join('|');if(part==='I'&&!/^([ABCD](\|[ABCD])*)$/.test(value))throw Error('QR có đáp án A/B/C/D không hợp lệ');out[part].push(value);
    }
   }
  }
  result[code]=out;
 }
 return result;
}
export function parseAnswerMatrix(rows,exam){
 if(!exam||!Array.isArray(rows)||!rows.length)throw Error('Chưa có kỳ hoặc tệp Excel trống');
 const first=String(rows[0]?.[0]??'').trim().toLocaleLowerCase('vi').replace(/\s+/g,'');
 if(!first.includes('câu\\mãđề')&&!first.includes('câu/mãđề')&&!first.includes('cau\\made')&&!first.includes('cau/made'))return null;
 const colcodes=rows[0].slice(1).map((x,i)=>[String(x??'').trim().replace(/\.0$/,''),i+1]).filter(x=>x[0]);
 if(!colcodes.length)throw Error('Mẫu DapAn không có cột mã đề');
 const n=exam.counts.I+exam.counts.II+exam.counts.III;if(rows.length<n+1)throw Error('Mẫu đáp án thiếu câu so với cấu hình môn học');
 const result={};
 for(const [raw,col] of colcodes){const code=raw.padStart(exam.digits,'0');if(!new RegExp('^\\d{'+exam.digits+'}$').test(code))throw Error('Mã đề khác loại phiếu: '+raw);const key={I:[],II:[],III:[]};
  for(let q=0;q<n;q++){
   const v=String(rows[q+1]?.[col]??'').trim();if(!v)throw Error(`Mã ${code}, dòng câu ${q+1} chưa có đáp án`);
   if(q<exam.counts.I){const value=v.toUpperCase().replace(/[\s,;\/|]/g,'');if(!/^([ABCD]{1,4}|ALL)$/.test(value))throw Error('Đáp án phần I phải A/B/C/D');key.I.push(value==='ALL'?'ALL':[...new Set(value)].join('|'));}
   else if(q<exam.counts.I+exam.counts.II){const vv=v.toUpperCase().replaceAll('D','Đ').replace(/\s+/g,'');if(!/^(ALL|[ĐS]{4})$/.test(vv))throw Error(`Phần II mã ${code} câu ${q-exam.counts.I+1} không hợp lệ`);key.II.push(vv);}
   else key.III.push(v);
  }result[code]=key;
 }
 return result;
}